"use client";
/* Gloop, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Gloop(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("gloop"); }, []);
  return React.createElement("piix-sprite", { "name": "gloop", ...piixAttrs(props) });
}

export default Gloop;
